package br.com.onda;
import android.app.*;
import android.content.*;
import android.content.res.AssetFileDescriptor;
import android.net.Uri;
import android.os.SystemClock;
import android.webkit.MimeTypeMap;
import android.widget.Toast;
import androidx.core.content.FileProvider;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

/** Explicit Android chooser. The user chooses the target app and confirms sending there. */
final class ShareMedia {
 interface Cancel {void check()throws IOException;}
 static Intent prepare(Context context,Uri source,String hint,String title,Cancel cancel)throws IOException{
  cancel.check();String scheme=source.getScheme();scheme=scheme==null?"":scheme.toLowerCase(Locale.ROOT);if("https".equals(scheme)||"http".equals(scheme)){if(source.getHost()==null||source.getUserInfo()!=null||source.toString().length()>16384)throw new IOException("Link inválido");return new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,source.toString()).putExtra(Intent.EXTRA_TITLE,title);}
  String mime=null;if("content".equals(scheme))mime=context.getContentResolver().getType(source);if(mime==null||mime.equals("application/octet-stream")){String extension=MimeTypeMap.getFileExtensionFromUrl(source.toString()).toLowerCase(Locale.ROOT);mime=MimeTypeMap.getSingleton().getMimeTypeFromExtension(extension);}if(mime==null||mime.equals("application/octet-stream"))mime=hint;if("application/x-matroska".equals(mime))mime="video/x-matroska";if("application/mp4".equals(mime))mime=hint!=null&&hint.startsWith("audio/")?"audio/mp4":"video/mp4";if("application/ogg".equals(mime))mime=hint!=null&&hint.startsWith("video/")?"video/ogg":"audio/ogg";if(mime!=null)mime=mime.split(";",2)[0].trim().toLowerCase(Locale.ROOT);if(mime==null||(!mime.startsWith("audio/")&&!mime.startsWith("video/")))throw new IOException("Escolha uma música ou vídeo");Uri shared=source;
  if("file".equals(scheme)){File original=new File(source.getPath());if(!original.isFile()||!original.canRead())throw new IOException("Arquivo indisponível");File base=new File(context.getCacheDir(),"shares");if(!base.isDirectory()&&!base.mkdirs())throw new IOException("Não foi possível preparar o arquivo");File[] old=base.listFiles();long now=System.currentTimeMillis();if(old!=null)for(File directory:old)if(directory.isDirectory()&&now-directory.lastModified()>24*60*60*1000L){File[] children=directory.listFiles();if(children!=null)for(File f:children)f.delete();directory.delete();}DownloadStorage.check(base,original.length());File directory=new File(base,UUID.randomUUID().toString());if(!directory.mkdir())throw new IOException("Não foi possível preparar o arquivo");String name=original.getName();int dot=name.lastIndexOf('.');String extension=dot>=0?name.substring(dot+1):"";String safe=DownloadLinks.filename(dot>0?name.substring(0,dot):name)+(extension.matches("[A-Za-z0-9]{1,8}")?"."+extension.toLowerCase(Locale.ROOT):"");File copy=new File(directory,safe);boolean complete=false;try{try(InputStream in=new FileInputStream(original);OutputStream out=new FileOutputStream(copy)){byte[] b=new byte[256*1024];int n;long last=0;while((n=in.read(b))!=-1){cancel.check();if(SystemClock.elapsedRealtime()-last>=1000){last=SystemClock.elapsedRealtime();DownloadStorage.check(base,0);}out.write(b,0,n);}}cancel.check();shared=FileProvider.getUriForFile(context,context.getPackageName()+".share",copy);complete=true;}finally{if(!complete){copy.delete();directory.delete();}}}
  else if("content".equals(scheme)){try(AssetFileDescriptor file=context.getContentResolver().openAssetFileDescriptor(source,"r")){if(file==null)throw new IOException("Arquivo indisponível");}cancel.check();}else throw new IOException("Tipo de arquivo não compartilhável");
  Intent send=new Intent(Intent.ACTION_SEND).setType(mime).putExtra(Intent.EXTRA_STREAM,shared).putExtra(Intent.EXTRA_TITLE,title).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(ClipData.newRawUri("Arquivo do Onda",shared));return send;
 }
 static void share(Activity activity,Uri source,String hint,String title){if(source==null)return;AtomicBoolean cancelled=new AtomicBoolean();AlertDialog progress=new AlertDialog.Builder(activity).setTitle("Compartilhar").setMessage("Preparando o arquivo para o seletor do Android…").setNegativeButton("Cancelar",(d,w)->cancelled.set(true)).create();progress.setOnCancelListener(d->cancelled.set(true));progress.show();ExecutorService worker=Executors.newSingleThreadExecutor();worker.execute(()->{try{Intent send=prepare(activity,source,hint,title,()->{if(cancelled.get()||activity.isFinishing()||activity.isDestroyed()||Thread.currentThread().isInterrupted())throw new InterruptedIOException("Cancelado");});activity.runOnUiThread(()->{try{progress.dismiss();}catch(Exception ignored){}if(cancelled.get()||activity.isFinishing()||activity.isDestroyed())return;try{Intent chooser=Intent.createChooser(send,"text/plain".equals(send.getType())?"Compartilhar link":"Compartilhar arquivo");chooser.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(send.getClipData()!=null)chooser.setClipData(send.getClipData());activity.startActivity(chooser);}catch(Exception e){Toast.makeText(activity,"Não foi possível abrir o compartilhamento deste arquivo",Toast.LENGTH_LONG).show();}});}catch(Exception error){activity.runOnUiThread(()->{try{progress.dismiss();}catch(Exception ignored){}if(!cancelled.get()&&!activity.isFinishing()&&!activity.isDestroyed())Toast.makeText(activity,error.getMessage()!=null&&error.getMessage().startsWith("Espaço livre")?"Espaço livre insuficiente para preparar uma cópia de compartilhamento":"Arquivo indisponível ou sem autorização para compartilhar",Toast.LENGTH_LONG).show();});}finally{worker.shutdown();}});}
}
